module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg disc,
    output reg flag,
    output reg err
);
    reg [2:0] cnt;
    reg [2:0] state;
    always @(posedge clk) begin
        if (reset) begin
            cnt <= 3'd0;
            state <= 3'd0;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            case (state)
                3'd0: begin
                    if (in) begin
                        cnt <= cnt + 1'b1;
                        state <= 3'd1;
                    end else begin
                        cnt <= 3'd0;
                    end
                end
                3'd1: begin
                    if (in) begin
                        cnt <= cnt + 1'b1;
                        if (cnt == 3'd5) begin
                            state <= 3'd2;
                            cnt <= 3'd0;
                        end
                    end else begin
                        cnt <= 3'd0;
                        state <= 3'd0;
                        disc <= 1'b1;
                    end
                end
                3'd2: begin
                    if (in) begin
                        cnt <= cnt + 1'b1;
                        if (cnt == 3'd6) begin
                            state <= 3'd0;
                            cnt <= 3'd0;
                            flag <= 1'b1;
                        end
                    end else begin
                        cnt <= 3'd0;
                        state <= 3'd0;
                        err <= 1'b1;
                    end
                end
            endcase
            if (state != 3'd2 && in) err <= 1'b1;
            else err <= 1'b0;
        end
    end
    always @(posedge clk) begin
        if (reset) disc <= 1'b0;
        else if (state == 3'd1 && in) disc <= 1'b1;
        else disc <= 1'b0;
    end
    always @(posedge clk) begin
        if (reset) flag <= 1'b0;
        else if (state == 3'd2 && in) flag <= 1'b1;
        else flag <= 1'b0;
    end
endmodule

