// Moore-type finite state machine to recognize HDLC framing sequences
module TopModule (
    input  clk,
    input  reset,
    input  in,
    output disc,
    output flag,
    output err
);
    reg [2:0] state;
    reg [2:0] next_state;
    wire disc_pulse;
    wire flag_pulse;
    wire err_pulse;
    reg [2:0] run_count;
    reg [2:0] next_run_count;
    reg [2:0] flag_count;
    reg [2:0] next_flag_count;
    always @(*) begin
        next_state = state;
        next_run_count = run_count;
        next_flag_count = flag_count;
        case (state)
            3'b000: if (in) begin next_state = 3'b001; next_run_count = 1; end
            3'b001: if (in) begin next_state = 3'b010; next_run_count = 2; end
            3'b010: if (in) begin next_state = 3'b011; next_run_count = 3; end
            3'b011: if (in) begin next_state = 3'b100; next_run_count = 4; end
            3'b100: if (in) begin next_state = 3'b101; next_run_count = 5; end
            3'b101: if (in) begin next_state = 3'b000; next_run_count = 0; next_flag_count = flag_count + 1; flag_pulse = 1; end
            3'b110: if (!in) begin next_state = 3'b000; next_run_count = 0; disc_pulse = 1; end
            default: if (in) begin next_state = 3'b110; next_run_count = 6; err_pulse = 1; end
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            run_count <= 0;
            flag_count <= 0;
        end else begin
            state <= next_state;
            run_count <= next_run_count;
            flag_count <= next_flag_count;
        end
    end
    assign disc = disc_pulse;
    assign flag = flag_pulse;
    assign err = err_pulse;
    always @(*) begin
        disc_pulse = (state == 3'b110 && run_count == 1);
        flag_pulse = (state == 3'b001 && run_count == 5) || (state == 3'b101 && run_count == 0);
        err_pulse = (state != 3'b000 && run_count >= 6);
    end
endmodule

